def reservoir_sample(stream, size, rng):
    if size < 0:
        raise ValueError('negative sample size')
    sample = []
    for seen, item in enumerate(stream, 1):
        if len(sample) < size:
            sample.append(item)
        else:
            slot = rng.randrange(seen)
            if slot < size:
                sample[slot] = item
    return sample

def kmp_find(text, pattern):
    if not pattern:
        return 0
    prefix = [0] * len(pattern)
    matched = 0
    for i in range(1, len(pattern)):
        while matched and pattern[i] != pattern[matched]:
            matched = prefix[matched - 1]
        if pattern[i] == pattern[matched]:
            matched += 1
        prefix[i] = matched
    matched = 0
    for i, char in enumerate(text):
        while matched and char != pattern[matched]:
            matched = prefix[matched - 1]
        if char == pattern[matched]:
            matched += 1
        if matched == len(pattern):
            return i - len(pattern) + 1
    return -1

def knapsack_value(weights, values, capacity):
    if capacity < 0 or len(weights) != len(values) or any(weight <= 0 for weight in weights):
        raise ValueError('invalid knapsack inputs')
    best = [0] * (capacity + 1)
    for weight, value in zip(weights, values):
        for room in range(capacity, weight - 1, -1):
            best[room] = max(best[room], best[room - weight] + value)
    return best[capacity]

def point_in_polygon(point, vertices):
    if len(vertices) < 3:
        raise ValueError('polygon needs three vertices')
    x, y = point
    inside = False
    for i, (ax, ay) in enumerate(vertices):
        bx, by = vertices[(i + 1) % len(vertices)]
        cross = (x - ax) * (by - ay) - (y - ay) * (bx - ax)
        if cross == 0 and min(ax, bx) <= x <= max(ax, bx) and min(ay, by) <= y <= max(ay, by):
            return True
        if (ay > y) != (by > y):
            crossing_x = ax + (y - ay) * (bx - ax) / (by - ay)
            if x < crossing_x:
                inside = not inside
    return inside

from collections import deque

def stable_matching(proposers, receivers):
    rank = {r: {p: i for i, p in enumerate(order)} for r, order in receivers.items()}
    free = deque(proposers)
    next_choice = {p: 0 for p in proposers}
    engaged = {}
    while free:
        proposer = free.popleft()
        order = proposers[proposer]
        if next_choice[proposer] == len(order):
            continue
        receiver = order[next_choice[proposer]]
        next_choice[proposer] += 1
        previous = engaged.get(receiver)
        if previous is None or rank[receiver][proposer] < rank[receiver][previous]:
            engaged[receiver] = proposer
            if previous is not None:
                free.append(previous)
        else:
            free.append(proposer)
    return {proposer: receiver for receiver, proposer in engaged.items()}

