from collections import Counter

def life_step(live_cells):
    neighbors = Counter()
    for x, y in live_cells:
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx or dy:
                    neighbors[(x + dx, y + dy)] += 1
    return {cell for cell, count in neighbors.items() if count == 3 or (count == 2 and cell in live_cells)}

