block = {(0, 0), (0, 1), (1, 0), (1, 1)}
assert life_step(block) == block
line = {(0, 0), (1, 0), (2, 0)}
assert life_step(line) == {(1, -1), (1, 0), (1, 1)}
assert life_step(life_step(line)) == line
assert life_step({(0, 0)}) == set()
assert life_step(set()) == set()

