answer = solve_linear([[2, 1], [1, -1]], [5, 1])
assert all(abs(a - b) < 1e-9 for a, b in zip(answer, [2, 1]))
answer = solve_linear([[0, 2], [1, 3]], [4, 7])
assert all(abs(a - b) < 1e-9 for a, b in zip(answer, [1, 2]))
try:
    solve_linear([[1, 2], [2, 4]], [3, 6])
except ValueError:
    pass
else:
    raise AssertionError('singular matrix accepted')

